const r = $('Find Critical').first().json.report || {};
const safety = Array.isArray(r.safety_pathology_unresolved) ? r.safety_pathology_unresolved : [];
const aftercare = Array.isArray(r.aftercare_urgent_open_24h) ? r.aftercare_urgent_open_24h : [];
const noSafety = Array.isArray(r.safety_unconfirmed_in_obra) ? r.safety_unconfirmed_in_obra : [];
const noEncargo = Array.isArray(r.no_encargo_in_obra) ? r.no_encargo_in_obra : [];
const total = r.total_critical || 0;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const sections = [];
if (safety.length > 0) {
  sections.push(`<h3 style="color:#c00;margin-top:24px">Patologias afectando seguridad SIN resolver (${safety.length})</h3>
<ul style="font-size:14px;line-height:1.6">${safety.map(s => `<li><b>${esc(s.project_name)}</b> [${esc(s.current_phase)}] - <span style="color:#c00">${esc(s.severity)}</span> ${esc(s.type)}: ${esc((s.description || '').substring(0,140))}...</li>`).join('')}</ul>`);
}
if (aftercare.length > 0) {
  sections.push(`<h3 style="color:#c00;margin-top:24px">Aftercare urgent/high abierto >24h (${aftercare.length})</h3>
<ul style="font-size:14px;line-height:1.6">${aftercare.map(a => `<li><b>${esc(a.project_name)}</b> - <span style="color:#c00">${esc(a.severity)}</span> ${esc(a.category || '?')} (${a.hours_open}h): ${esc(a.desc_preview)}...</li>`).join('')}</ul>`);
}
if (noSafety.length > 0) {
  sections.push(`<h3 style="color:#e67e22;margin-top:24px">Proyectos en obra SIN safety_plan confirmado (${noSafety.length})</h3>
<p style="font-size:13px;color:#555">Obligatorio por RD 1627/1997. Disparar agent_safety_plan y confirmar.</p>
<ul style="font-size:14px">${noSafety.map(p => `<li><b>${esc(p.project_name)}</b> - fase ${esc(p.current_phase)}</li>`).join('')}</ul>`);
}
if (noEncargo.length > 0) {
  sections.push(`<h3 style="color:#e67e22;margin-top:24px">Proyectos en obra SIN encargo profesional firmado (${noEncargo.length})</h3>
<p style="font-size:13px;color:#555">Riesgo legal/profesional. POST /webhook/contract-generate contract_type=encargo_profesional.</p>
<ul style="font-size:14px">${noEncargo.map(p => `<li><b>${esc(p.project_name)}</b> - fase ${esc(p.current_phase)}</li>`).join('')}</ul>`);
}

const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:780px">
<div style="background:#fee;border-left:4px solid #c00;padding:14px 18px;border-radius:4px;margin-bottom:18px">
  <h2 style="margin:0;color:#c00">[CRITICO] ${total} situaciones criticas detectadas</h2>
  <p style="margin:6px 0 0;font-size:13px;color:#555">Cron cada 6h vigila condiciones donde un compliance audit retornaria grade=D inmediato.</p>
</div>
${sections.join('\n')}
<p style="font-size:12px;color:#888;margin-top:24px">cron_compliance_critical_alert - generado ${new Date().toISOString()}<br>Para audit detallado: <code>POST /webhook/audit-project</code>. Vista panoramica: <code>GET /webhook/admin-compliance-overview</code>.</p>
</div>`;

const subject = `[CRITICO compliance] ${total} situaciones (${safety.length} safety + ${aftercare.length} aftercare + ${noSafety.length + noEncargo.length} legal)`;
return [{ json: { html, subject, total } }];
